<?php require 'includes/auth.php';require_login();$id=(int)($_GET['order']??0);$s=$pdo->prepare("SELECT o.*,u.email FROM orders o JOIN users u ON u.id=o.user_id WHERE o.id=?");$s->execute([$id]);$o=$s->fetch();if(!$o||($o['user_id']!=user()['id']&&!admin()))die('Invoice tidak ditemukan');$s=$pdo->prepare("SELECT oi.*,p.name FROM order_items oi JOIN products p ON p.id=oi.product_id WHERE oi.order_id=?");$s->execute([$id]);$items=$s->fetchAll();?><!doctype html><html lang=id><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><link rel=stylesheet href=assets/style.css><title>Invoice <?=$o['order_no']?></title></head><body><main class=invoice><h1>HK PRINTING</h1><p>Invoice: <b><?=e($o['order_no'])?></b><br>Status: <?=e($o['status'])?></p><hr><?php foreach($items as $i):?><div class=line><span><?=e($i['name'])?> × <?=$i['qty']?></span><b><?=rupiah($i['qty']*$i['price'])?></b></div><?php endforeach;?><h2>Total <?=rupiah($o['total'])?></h2><a class=btn target=_blank href="https://wa.me/<?=wa_number()?>?text=Halo%20HK%20PRINTING,%20saya%20sudah%20order%20<?=e($o['order_no'])?>">Konfirmasi WhatsApp</a></main></body></html>
